<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowLeft,ArrowRight,Plus} from 'lucide-vue-next'
import Panel from '../components/Panel.vue'
import Modal from '../components/Modal.vue'
import TelemetryChart from '../components/TelemetryChart.vue'
import {useWorkspace} from '../stores/workspace'
import {causesFor,samplesFor} from '../services/demo'
import {metricInfo,statusText} from '../domain'
import {time} from '../utils'
const listPage=ref(1)
const store=useWorkspace(),route=useRoute(),router=useRouter(),showList=ref(false),showForm=ref(false),scatter=ref(true),filter=ref(''),all=ref(false),query=ref(''),detectionId=ref(''),selection=ref<string[]>([]),error=ref(''),scenario=ref<'success'|'failure'>('success')
const tasks=computed(()=>store.state.analyses.filter(a=>(all.value||a.context.segment.id===store.context?.segment.id)&&(!filter.value||a.status===filter.value)&&(!query.value||a.id.includes(query.value)))),task=computed(()=>route.params.id?store.state.analyses.find(a=>a.id===route.params.id):tasks.value[0]),detection=computed(()=>store.state.detections.find(d=>d.id===task.value?.detectionId)),available=computed(()=>store.state.detections.filter(d=>d.status==='success'&&d.anomalies.length&&d.context.segment.id===store.context?.segment.id)),source=computed(()=>available.value.find(d=>d.id===detectionId.value)),anomalies=computed(()=>detection.value?.anomalies.filter(a=>task.value?.anomalyIds.includes(a.id))??[])
const causes=computed(()=>detection.value&&task.value?causesFor(detection.value,task.value.anomalyIds):[]),hasCorrelation=computed(()=>!!detection.value?.metrics.includes('return')&&!!detection.value?.metrics.includes('flow')),features=computed(()=>detection.value?.metrics.map(m=>{const hit=anomalies.value.find(a=>a.metric===m),rows=samplesFor(task.value!.context,detection.value!.start,detection.value!.end).filter(s=>s.metric===m);return {metric:m,value:hit?.value??rows[0]?.value??'—',anomaly:!!hit}})??[])
const listRows=computed(()=>tasks.value.slice((listPage.value-1)*20,listPage.value*20)),listPages=computed(()=>Math.max(1,Math.ceil(tasks.value.length/20)))
watch([query,filter,all],()=>listPage.value=1)
watch(hasCorrelation,v=>{if(!v)scatter.value=false},{immediate:true})
watch(detectionId,()=>selection.value=source.value?.anomalies.map(a=>a.id)??[]);watch(()=>task.value?.id,()=>showList.value=false)
function open(){detectionId.value=available.value[0]?.id??'';selection.value=source.value?.anomalies.map(a=>a.id)??[];error.value='';showForm.value=true}
function submit(){try{const id=store.createAnalysis(detectionId.value,selection.value,scenario.value);showForm.value=false;router.push('/analysis/'+id)}catch(e){error.value=(e as Error).message}}
function retry(){if(task.value)router.push('/analysis/'+store.createAnalysis(task.value.detectionId,task.value.anomalyIds,'success',task.value.id))}
function report(){if(task.value)router.push('/reports/'+store.createReport(task.value.detectionId,task.value.id))}
</script>
<template><div class="page-stack"><div class="page-actions"><div class="flex wrap"><h2>AI 分析</h2><span class="badge purple">自研小模型辅助诊断 · 演示</span></div><div class="flex"><button class="secondary" @click="showList=!showList">{{showList?'收起任务记录':'任务记录'}}</button><button class="primary" @click="open"><Plus :size="16"/>新建分析</button></div></div>
<Panel v-if="showList||!task" title="历史 AI 分析任务"><div class="filter-bar"><input v-model="query" placeholder="搜索分析编号" aria-label="搜索分析任务"/><select v-model="filter" aria-label="分析任务状态"><option value="">全部状态</option><option v-for="(text,s) in statusText" :key="s" :value="s">{{text}}</option></select><label class="check-label"><input v-model="all" type="checkbox"/>全部管段</label></div><div class="table-wrap"><table><thead><tr><th>分析编号</th><th>管段</th><th>来源检测</th><th>模型版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="a in listRows" :key="a.id"><td class="mono">{{a.id}}</td><td>{{a.context.segment.name}}</td><td>{{a.detectionId}}</td><td>{{a.model}}</td><td><span :class="['badge',a.status==='failed'?'red':'green']">{{statusText[a.status]}}</span></td><td><RouterLink :to="'/analysis/'+a.id" class="text-button">查看</RouterLink></td></tr><tr v-if="!tasks.length"><td colspan="6" class="empty">当前范围暂无分析任务，请先完成异常检测。</td></tr></tbody></table></div><div class="pagination"><span>共 {{tasks.length}} 条 · 第 {{listPage}} / {{listPages}} 页</span><button :disabled="listPage===1" @click="listPage--">上一页</button><button :disabled="listPage>=listPages" @click="listPage++">下一页</button></div></Panel>
<template v-if="task"><Panel><div class="flex wrap between"><div class="stack-small"><div class="flex wrap"><span class="badge orange">任务编号 {{task.id}}</span><span class="badge">关联检测任务：{{task.detectionId}}</span><span :class="['badge',task.status==='failed'?'red':'green']">{{statusText[task.status]}}</span></div><p>分析模型：<b>{{task.model}}</b>　<span class="muted">创建时间：{{time(task.createdAt)}}</span></p><p class="muted">{{task.context.enterprise.name}} / {{task.context.network.name}} / <b class="orange">{{task.context.segment.name}}</b></p></div><div class="flex wrap"><RouterLink class="secondary" :to="{path:'/detections/'+task.detectionId,query:{selected:task.anomalyIds.join(',')}}"><ArrowLeft :size="15"/>返回检测结果</RouterLink><button class="primary" :disabled="task.status!=='success'" @click="report">生成综合诊断报告</button></div></div></Panel>
<Panel v-if="task.status==='failed'" title="分析未完成"><p class="error">{{task.error}}</p><button class="primary mt" @click="retry">重试分析</button></Panel><Panel v-else-if="task.status!=='success'" title="AI 分析执行中"><div class="task-running"><span class="loader"></span><h3>{{statusText[task.status]}}</h3><p class="muted">正在处理选定异常的演示数据，可离开后从任务记录恢复查看。</p></div></Panel>
<template v-else><div class="grid ai-top"><Panel title="三级资产定位"><div class="asset-level"><span>一级：所属供热企业</span><strong>{{task.context.enterprise.name}}</strong><small>{{task.context.enterprise.code}}</small></div><div class="asset-level"><span>二级：供热管网系统</span><strong>{{task.context.network.name}}</strong><small>{{task.context.network.code}}</small></div><div class="asset-level target-object"><span>三级：当前分析管段</span><strong class="orange">{{task.context.segment.name}}</strong><small>DN{{task.context.segment.diameter}} / {{task.context.segment.length}}m</small></div><p class="muted small">来源对象已固定；切换当前管段不会修改本任务。</p></Panel><Panel title="多维时序特征提取摘要"><template #tools><span class="muted">示例特征 · 非实际模型推理</span></template><div class="grid metrics-four ai-metrics"><div v-for="f in features" :key="f.metric" class="metric-card"><span class="muted">{{metricInfo[f.metric].label}}</span><div class="metric-value" :style="{color:metricInfo[f.metric].color}">{{f.value}}<small>{{metricInfo[f.metric].unit}}</small></div><span :class="['badge',f.anomaly?'red':'green']">{{f.anomaly?'异常变化':'特征参考'}}</span><p class="muted">可用时间片段与检测结果对齐</p></div></div><div class="inset mt">分析异常：{{anomalies.map(a=>a.title).join('、')}}<p class="muted">参数事实来自检测任务；以下原因与权重为演示推测，需现场验证。</p></div></Panel></div>
<div class="grid two-one"><Panel :title="hasCorrelation?'特征关联分析：回水温度变化与流量变化':'已选参数时序与分析限制'"><template #tools><div class="segmented"><button :disabled="!hasCorrelation" :class="{selected:scatter}" @click="scatter=true">关联散点流</button><button :class="{selected:!scatter}" @click="scatter=false">双轴时序对齐</button></div></template><div v-if="hasCorrelation" class="flex between wrap"><span>示例负相关系数 <b class="red mono">-0.84</b></span><span class="muted">关联不等于因果</span></div><TelemetryChart :key="String(scatter)" :context="task.context" :scatter="scatter" :metrics="hasCorrelation?['return','flow']:(detection?.metrics??[])" :start="detection?.start" :end="detection?.end" :anomalies="anomalies"/><div class="inset muted">{{hasCorrelation?'水力平衡变化：演示关联仅作为核查方向。':'本任务缺少回水温度或流量参数，未进行温度与流量关联分析，仅展示已选参数。'}}</div></Panel><Panel title="模型局部敏感性归因（示例）"><template #tools><span class="badge orange">ThermalNet-Mini</span></template><p class="muted">演示参数贡献权重分解，不代表已执行 SHAP 计算。</p><div v-for="(f,i) in features" :key="f.metric" class="weight large-weight"><div class="flex between"><span>{{metricInfo[f.metric].label}}</span><b :style="{color:['#fb7a18','#4ea8ff','#a855f7','#b0b6c2'][i]}">{{[44.2,31.6,16.4,7.8][i]}}%</b></div><div class="bar"><span :style="{width:[44.2,31.6,16.4,7.8][i]+'%',background:['#fb7a18','#4ea8ff','#a855f7','#b0b6c2'][i]}"></span></div></div><div class="inset mt"><h3 class="green">机理约束参考</h3><p class="mono">Q = c · m · (T供 - T回)</p><p class="muted">需结合实际参数、设备状态与人工核查判断。</p></div></Panel></div>
<Panel title="可能原因研判"><template #tools><span class="muted">示例权重排序 · 非确定性结论</span></template><div class="grid cause-grid"><article v-for="(cause,i) in causes" :key="cause.title" class="cause-card"><div class="flex between wrap"><h3>{{i+1}}. {{cause.title}}</h3><span :class="['badge',i===0?'red':'amber']">示例权重 {{cause.weight}}%</span></div><h4 class="muted mt">分析依据</h4><p>{{cause.evidence}}</p><div class="inset"><strong class="orange">建议核查方向</strong><p>{{cause.check}}</p></div></article></div></Panel>
<Panel title="现场核查方向与工程运维建议"><div class="grid bottom-three"><article v-for="(cause,i) in causes" :key="cause.title" class="inset"><span class="orange">排查优先级 {{i+1}}</span><h3 class="mt">{{cause.title}}</h3><p>{{cause.check}}</p></article></div></Panel><div class="notice">本页分析由前端演示服务产生，模型名称、权重与特征均为示例。请区分观测事实与可能原因；不提供设备调控或派发工单。<button class="text-button" @click="report">生成报告 <ArrowRight :size="14"/></button></div></template></template>
<Modal v-if="showForm" title="创建 AI 分析任务" @close="showForm=false"><form class="form-stack" @submit.prevent="submit"><label>来源检测任务<select v-model="detectionId" required><option value="">请选择已完成的异常检测</option><option v-for="d in available" :key="d.id" :value="d.id">{{d.name}} · {{d.id}}</option></select></label><p v-if="!available.length" class="muted">当前管段没有可分析异常，<RouterLink to="/detections?create=1" class="text-button" @click="showForm=false">先发起检测</RouterLink>。</p><fieldset><legend>送入分析的异常</legend><label v-for="a in source?.anomalies" :key="a.id" class="check-label"><input v-model="selection" :value="a.id" type="checkbox"/>{{a.title}}</label></fieldset><label>模型<input value="ThermalNet-Mini v1.8（演示）" readonly/></label><label>演示场景<select v-model="scenario"><option value="success">分析完成</option><option value="failure">分析失败（验证重试）</option></select></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="!source">开始分析</button></form></Modal>
</div></template>
